parameters.jsCode:
const firstItem = $input.first();
const item = firstItem ? firstItem.json : {};


// ====================================================
// Utility Functions
// ====================================================

function parseMaybe(value) {
  if (value === null || value === undefined) {
    return {};
  }

  if (typeof value === 'object') {
    return value;
  }

  const cleaned = String(value)
    .trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  return JSON.parse(cleaned);
}


function toNumber(value, fallback = 0) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return fallback;
  }

  const cleaned = String(value)
    .replace(/,/g, '')
    .replace(/USD/gi, '')
    .replace(/KG/gi, '')
    .replace(/CBM/gi, '')
    .trim();

  const num = Number(cleaned);

  return Number.isFinite(num)
    ? num
    : fallback;
}


function toDate(value) {
  if (!value) {
    return null;
  }

  const date = new Date(value);

  return Number.isNaN(date.getTime())
    ? null
    : date;
}


// ====================================================
// 1. Parse Agent Output
// ====================================================

let raw =
  item.output ??
  item.text ??
  item.response ??
  item;

let parsed = parseMaybe(raw);


// output wrapper 제거
if (
  parsed &&
  typeof parsed === 'object' &&
  parsed.output !== undefined
) {
  parsed = parseMaybe(parsed.output);
}


// ====================================================
// 2. Extract Carrier Schedules
// ====================================================

const carrierSchedules =
  parsed.Carrier_Schedules ?? {};

const hmmSchedules =
  Array.isArray(carrierSchedules.HMM)
    ? carrierSchedules.HMM
    : [];

const mscSchedules =
  Array.isArray(carrierSchedules.MSC)
    ? carrierSchedules.MSC
    : [];

const maerskSchedules =
  Array.isArray(carrierSchedules.MAERSK)
    ? carrierSchedules.MAERSK
    : [];


// ====================================================
// 3. Extract Request Summary
//    두 가지 nesting 모두 지원
// ====================================================

const request =
  parsed.Request_Summary ??
  carrierSchedules.Request_Summary ??
  {};


// ====================================================
// 4. Normalize Request
// ====================================================

const requestedDepartureDate =
  toDate(request.Request_Departure_Date_Time);

const requestedContainers =
  toNumber(request.Container_40, 0);

const requestedWeight =
  toNumber(request.Weight_KG, 0);

const requestedCBM =
  toNumber(request.Dimension_CBM, 0);


// Request Summary가 제대로 들어왔는지 검증
if (!requestedDepartureDate) {
  throw new Error(
    `Request_Departure_Date_Time is missing or invalid. Request_Summary: ${JSON.stringify(request)}`
  );
}

if (requestedContainers <= 0) {
  throw new Error(
    `Container_40 is missing or invalid. Request_Summary: ${JSON.stringify(request)}`
  );
}


// ====================================================
// 5. Schedule Evaluation
// ====================================================

function evaluateSchedule(schedule) {

  const etd =
    toDate(schedule.ETD);

  const availableContainers =
    toNumber(
      schedule.Available_Container,
      0
    );

  const maxPayloadPerContainer =
    toNumber(
      schedule.Max_Payload_KG_Per_Container,
      0
    );

  const maxCbmPerContainer =
    toNumber(
      schedule.Max_CBM_Per_Container,
      0
    );


  // --------------------------------------------------
  // Condition 1
  // ETD >= Requested Departure Date
  // --------------------------------------------------

  const etdPassed =
    etd !== null &&
    etd >= requestedDepartureDate;


  // --------------------------------------------------
  // Condition 2
  // Available containers >= Requested containers
  // --------------------------------------------------

  const containerPassed =
    availableContainers >= requestedContainers;


  // --------------------------------------------------
  // Condition 3
  // Total capacity of requested containers
  // --------------------------------------------------

  const totalPayloadCapacity =
    availableContainers *
    maxPayloadPerContainer;

  const totalCbmCapacity =
    availableContainers *
    maxCbmPerContainer;


  const weightPassed =
    totalPayloadCapacity >=
    requestedWeight;

  const cbmPassed =
    totalCbmCapacity >=
    requestedCBM;


  // --------------------------------------------------
  // Final Eligibility
  // --------------------------------------------------

  const eligible =
    etdPassed &&
    containerPassed &&
    weightPassed &&
    cbmPassed;


  return {
    ...schedule,

    Eligibility: {
      ETD_Passed: etdPassed,
      Container_Passed: containerPassed,
      Weight_Passed: weightPassed,
      CBM_Passed: cbmPassed,
      Eligible: eligible
    },

    Capacity_Check: {
      Requested_Containers:
        requestedContainers,

      Requested_Weight_KG:
        requestedWeight,

      Requested_CBM:
        requestedCBM,

      Max_Payload_KG_Per_Container:
        maxPayloadPerContainer,

      Max_CBM_Per_Container:
        maxCbmPerContainer,

      Total_Payload_Capacity_KG:
        totalPayloadCapacity,

      Total_CBM_Capacity:
        totalCbmCapacity
    }
  };
}


// ====================================================
// 6. Evaluate
// ====================================================

const evaluatedHMM =
  hmmSchedules.map(evaluateSchedule);

const evaluatedMSC =
  mscSchedules.map(evaluateSchedule);

const evaluatedMAERSK =
  maerskSchedules.map(evaluateSchedule);


// ====================================================
// 7. Filter Eligible Schedules
// ====================================================

const filteredHMM =
  evaluatedHMM.filter(
    row => row.Eligibility.Eligible
  );

const filteredMSC =
  evaluatedMSC.filter(
    row => row.Eligibility.Eligible
  );

const filteredMAERSK =
  evaluatedMAERSK.filter(
    row => row.Eligibility.Eligible
  );


// ====================================================
// 8. Final Output
// ====================================================

return [
  {
    json: {

      Carrier_Schedules: {
        HMM: filteredHMM,
        MSC: filteredMSC,
        MAERSK: filteredMAERSK
      },

      Filter_Metadata: {

        original_rows: {
          HMM: hmmSchedules.length,
          MSC: mscSchedules.length,
          MAERSK: maerskSchedules.length,

          total:
            hmmSchedules.length +
            mscSchedules.length +
            maerskSchedules.length
        },

        filtered_rows: {
          HMM: filteredHMM.length,
          MSC: filteredMSC.length,
          MAERSK: filteredMAERSK.length,

          total:
            filteredHMM.length +
            filteredMSC.length +
            filteredMAERSK.length
        },

        filters_applied: [
          "ETD >= Request_Departure_Date_Time",
          "Available_Container >= Container_40",
          "Available_Container × Max_Payload_KG_Per_Container >= Weight_KG",
          "Available_Container × Max_CBM_Per_Container >= Dimension_CBM"
        ]
      },

      Request_Summary: request
    }
  }
];

const input = $input.first().json;

// ---------------------------------------------
// 1. Read carrier schedules
// ---------------------------------------------
const carrierSchedules = input.Carrier_Schedules ?? {};

// ---------------------------------------------
// 2. Flatten schedules across all carriers
// ---------------------------------------------
const flattenedSchedules = [];

for (const [carrierName, schedules] of Object.entries(carrierSchedules)) {

  if (!Array.isArray(schedules)) {
    continue;
  }

  for (const schedule of schedules) {

    flattenedSchedules.push({
      ...schedule,

      // Add Carrier only if it is not already provided
      Carrier: schedule.Carrier ?? carrierName
    });
  }
}

// ---------------------------------------------
// 3. Return Strategy-Agent-friendly structure
// ---------------------------------------------
return [
  {
    json: {
      "Carrier agent": flattenedSchedules,

      "Request_Summary": input.Request_Summary ?? null,

      "Filter_Metadata": input.Filter_Metadata ?? null
    }
  }
];

const input = $input.first().json;

return [
  {
    json: input.output ?? input
  }
];

