const input = $input.first().json;

const data = input.callback_query.data;

const [decision_id, action, selected_option] = data.split('|');

return [
  {
    json: {
      decision_id: decision_id,
      action: action,
      selected_option: selected_option
    }
  }
];

const options = $input.all().map(item => item.json);

return [
  {
    json: {
      Data: JSON.stringify(options)
    }
  }
];

const row = $input.first().json;

if (!row) {
  throw new Error("Recommendation 데이터를 찾을 수 없습니다.");
}

if (!row.Data) {
  throw new Error("Data 컬럼이 비어 있습니다.");
}

let options;

try {
  options =
    typeof row.Data === "string"
      ? JSON.parse(row.Data)
      : row.Data;
} catch (error) {
  throw new Error(
    `Data 컬럼의 JSON을 파싱할 수 없습니다: ${error.message}`
  );
}

if (!Array.isArray(options)) {
  throw new Error("Data가 StrategyOption 배열이 아닙니다.");
}

return [
  {
    json: {
      requestID: row.requestID ?? row.Request_ID ?? "",
      options: options
    }
  }
];

// ============================================================
// Strategy Agent 결과 → Web StrategyOption 형식으로 변환
// ============================================================

const input = $input.first().json;

// Context가 최상위에 있다고 가정
const context = input.Context;

if (!context) {
  throw new Error("Context를 찾을 수 없습니다.");
}

if (!context.options) {
  throw new Error("Context.options를 찾을 수 없습니다.");
}

const {
  lowest_cost,
  fastest_arrival,
  balanced
} = context.options;


// ------------------------------------------------------------
// Risk Level → 한글 Label
// ------------------------------------------------------------

function getRiskLabel(riskLevel) {
  const risk = String(riskLevel || "").toUpperCase();

  if (risk === "LOW") return "낮음";
  if (risk === "MEDIUM") return "중간";
  if (risk === "HIGH") return "높음";

  return "중간";
}


// ------------------------------------------------------------
// Risk Level → 웹 Progress Bar용 숫자
// ------------------------------------------------------------

function getRiskScore(riskLevel) {
  const risk = String(riskLevel || "").toUpperCase();

  if (risk === "LOW") return 20;
  if (risk === "MEDIUM") return 50;
  if (risk === "HIGH") return 80;

  return 50;
}


// ------------------------------------------------------------
// Risk Level → Agent Status
// ------------------------------------------------------------

function getAgentStatus(riskLevel) {
  const risk = String(riskLevel || "").toUpperCase();

  if (risk === "LOW") return "approved";
  if (risk === "MEDIUM") return "warning";
  if (risk === "HIGH") return "warning";

  return "warning";
}


// ------------------------------------------------------------
// 비용 Formatting
//
// 13200 → "$13,200"
// ------------------------------------------------------------

function formatCost(cost) {
  const value = Number(cost);

  if (Number.isNaN(value)) {
    return "$0";
  }

  return `$${value.toLocaleString("en-US")}`;
}


// ------------------------------------------------------------
// POL → POD
// ------------------------------------------------------------

function makePortPair(option) {
  return `${option.POL} -> ${option.POD}`;
}


// ------------------------------------------------------------
// Tooltip 생성
//
// Market + Historical 정보를 같이 보여줌
// ------------------------------------------------------------

function makeTooltip(option) {
  const parts = [];

  if (option.Market_Assessment) {
    parts.push(
      `시장 리스크: ${option.Market_Assessment}`
    );
  }

  if (option.Historical_Assessment) {
    parts.push(
      option.Historical_Assessment
    );
  }

  return parts.join(" ");
}


// ------------------------------------------------------------
// Recommendation Quote
// ------------------------------------------------------------

function makeQuote(option) {
  if (!option.selection_reason) {
    return "";
  }

  return `"${option.selection_reason}"`;
}


// ============================================================
// Option A
// Lowest Cost
// ============================================================

const optionA = {

  optionId: "A",

  title: "비용 최적화",

  subtitle: "운임 최소화 지향",

  icon: "savings",

  costUsd:
    formatCost(
      lowest_cost.Calculated_Total_Cost_USD
    ),

  costPerUnit: "/TEU",

  leadTimeDays:
    Number(lowest_cost.Transit_Days || 0),

  riskScoreLabel:
    getRiskLabel(
      lowest_cost.Risk_Level
    ),

  riskScoreValue:
    getRiskScore(
      lowest_cost.Risk_Level
    ),

  recommendationQuote:
    makeQuote(lowest_cost),

  agent6Status:
    getAgentStatus(
      lowest_cost.Risk_Level
    ),

  agent6Tooltip:
    makeTooltip(lowest_cost),

  isRecommended:
    context.ai_preferred_option ===
    "lowest_cost",

  vesselName:
    lowest_cost.Carrier || "",

  portPair:
    makePortPair(lowest_cost),

  eta:
    lowest_cost.ETA || ""
};


// ============================================================
// Option B
// Fastest Arrival
// ============================================================

const optionB = {

  optionId: "B",

  title: "속도 최적화",

  subtitle: "최단 리드타임 직항",

  icon: "bolt",

  costUsd:
    formatCost(
      fastest_arrival.Calculated_Total_Cost_USD
    ),

  costPerUnit: "/TEU",

  leadTimeDays:
    Number(fastest_arrival.Transit_Days || 0),

  riskScoreLabel:
    getRiskLabel(
      fastest_arrival.Risk_Level
    ),

  riskScoreValue:
    getRiskScore(
      fastest_arrival.Risk_Level
    ),

  recommendationQuote:
    makeQuote(fastest_arrival),

  agent6Status:
    getAgentStatus(
      fastest_arrival.Risk_Level
    ),

  agent6Tooltip:
    makeTooltip(fastest_arrival),

  isRecommended:
    context.ai_preferred_option ===
    "fastest_arrival",

  vesselName:
    fastest_arrival.Carrier || "",

  portPair:
    makePortPair(fastest_arrival),

  eta:
    fastest_arrival.ETA || ""
};


// ============================================================
// Option C
// Balanced
// ============================================================

const optionC = {

  optionId: "C",

  title: "균형 잡힌 가치",

  subtitle: "비용과 속도의 조화",

  icon: "balance",

  costUsd:
    formatCost(
      balanced.Calculated_Total_Cost_USD
    ),

  costPerUnit: "/TEU",

  leadTimeDays:
    Number(balanced.Transit_Days || 0),

  riskScoreLabel:
    getRiskLabel(
      balanced.Risk_Level
    ),

  riskScoreValue:
    getRiskScore(
      balanced.Risk_Level
    ),

  recommendationQuote:
    makeQuote(balanced),

  agent6Status:
    getAgentStatus(
      balanced.Risk_Level
    ),

  agent6Tooltip:
    makeTooltip(balanced),

  isRecommended:
    context.ai_preferred_option ===
    "balanced",

  vesselName:
    balanced.Carrier || "",

  portPair:
    makePortPair(balanced),

  eta:
    balanced.ETA || ""
};


// ============================================================
// n8n에서는 각각 하나의 Item으로 반환
// ============================================================

return [
  {
    json: optionA
  },
  {
    json: optionB
  },
  {
    json: optionC
  }
];

// ============================================================
// 1. Replan Classifier
// output 안에 JSON string이 들어있으므로 parsing
// ============================================================

const replanRaw = $('Replan classifier1').first().json.output;
const replan = JSON.parse(replanRaw);


// ============================================================
// 2. Original Request
// ============================================================

const original = $('Generate Request ID').first().json;


// ============================================================
// 3. Changes
// ============================================================

const changes = replan.changes ?? {};


// ============================================================
// 4. Helper
// 새로운 값이 있으면 사용
// null / undefined이면 기존 값을 유지
// ============================================================

const resolve = (newValue, oldValue) => {
  if (newValue !== null && newValue !== undefined && newValue !== "") {
    return newValue;
  }

  return oldValue ?? null;
};


// ============================================================
// 5. Build Resolved Request
// ============================================================

const resolvedRequest = {

  // ------------------------
  // Identification
  // ------------------------
  requestID: original.requestID ?? null,


  // ------------------------
  // Route
  // ------------------------
  POL: resolve(
    changes.POL,
    original.POL
  ),

  POD: resolve(
    changes.POD,
    original.POD
  ),


  // ------------------------
  // Schedule
  // ------------------------
  Request_Departure_Date_Time: resolve(
    changes.Request_Departure_Date_Time,
    original.Request_Departure_Date_Time
  ),

  Departure_Flexibility_Days:
    original.Departure_Flexibility_Days ?? null,

  Latest_Arrival_Date:
    changes.Latest_Arrival_Date ?? null,


  // ------------------------
  // Cargo
  // ------------------------
  Container_40: resolve(
    changes.Container_40,
    original["Container 40"]
  ),

  Container_Type: resolve(
    changes.Container_Type,
    original.Container_Type
  ),

  Weight_KG: resolve(
    changes.Weight_KG,
    original["Weight (kg)"]
  ),

  Dimension_CBM: resolve(
    changes.Dimension_CBM,
    original["Dimension (CBM)"]
  ),

  Dangerous_Goods: resolve(
    changes.Dangerous_Goods,
    original.Dangerous_Goods
  ),


  // ------------------------
  // Additional constraints
  // ------------------------
  Max_Total_Cost_USD:
    changes.Max_Total_Cost_USD ?? null,

  Direct_Only:
    changes.Direct_Only ?? null,

  Excluded_Carriers:
    changes.Excluded_Carriers ?? null,

  Preferred_Carriers:
    changes.Preferred_Carriers ?? null,

  Max_Transshipments:
    changes.Max_Transshipments ?? null,

  Max_Transit_Days:
    changes.Max_Transit_Days ?? null,

  Max_Risk_Level:
    changes.Max_Risk_Level ?? null
};


// ============================================================
// 6. Return
// ============================================================

return [
  {
    json: {
      replan_type: replan.replan_type,

      Resolved_Request: resolvedRequest,

      change_summary: replan.change_summary ?? null,
      routing_reason: replan.routing_reason ?? null,
      requires_clarification: replan.requires_clarification ?? false,
      clarification_question: replan.clarification_question ?? null,
      original_message: replan.original_message ?? null
    }
  }
];

const input = $input.first().json;

// --------------------------------------------------
// 1. Agent structured output 가져오기
// --------------------------------------------------

const data = input.output ?? input;


// --------------------------------------------------
// 2. Helper
// --------------------------------------------------

const value = (v) => {
  if (v === null || v === undefined || v === "") {
    return "N/A";
  }
  return v;
};

const formatCost = (v) => {
  if (v === null || v === undefined || v === "") {
    return null;
  }

  const num = Number(v);

  if (Number.isNaN(num)) {
    return String(v);
  }

  return num.toLocaleString("en-US");
};


// --------------------------------------------------
// 3. 기본 메시지
// --------------------------------------------------

let message = `🔎 운송 일정 재검색 결과

${value(data.telegram_summary)}

━━━━━━━━━━━━━━━━━━━━`;


// --------------------------------------------------
// 4. FOUND
// --------------------------------------------------

if (data.status === "FOUND") {

  const schedules = Array.isArray(data.matched_schedules)
    ? data.matched_schedules
    : [];

  message += `

✅ 요청하신 조건에 맞는 일정 ${schedules.length}건을 찾았습니다.`;

  schedules.forEach((s, index) => {

    message += `

━━━━━━━━━━━━━━━━━━━━

🚢 후보 ${index + 1}

선사: ${value(s.Carrier)}`;

    if (s.Vessel_Name) {
      message += `
선박: ${s.Vessel_Name}`;
    }

    if (s.Voyage_No) {
      message += `
Voyage: ${s.Voyage_No}`;
    }

    message += `
출항일: ${value(s.ETD)}
도착일: ${value(s.ETA)}`;

    if (s.Route_Code) {
      message += `
노선: ${s.Route_Code}`;
    }

    if (s.Real_Route) {
      message += `
경로: ${s.Real_Route}`;
    }

    if (
      s.Available_Container !== null &&
      s.Available_Container !== undefined
    ) {
      message += `
가용 컨테이너: ${s.Available_Container}개`;
    }

    const cost = formatCost(s.Calculated_Total_Cost_USD);

    if (cost !== null) {
      message += `
예상 운임: USD ${cost}`;
    }

    if (
      s.Transit_Days !== null &&
      s.Transit_Days !== undefined
    ) {
      message += `
운송 기간: ${s.Transit_Days}일`;
    }

    if (s.Risk_Level) {
      message += `
리스크: ${s.Risk_Level}`;
    }

    if (s.reason) {
      message += `

💬 선정 이유
${s.reason}`;
    }
  });

  message += `

━━━━━━━━━━━━━━━━━━━━

원하시는 일정이 있으시면 해당 옵션을 말씀해 주세요.
추가 조건을 주시면 다시 검색해드릴 수도 있습니다.`;


// --------------------------------------------------
// 5. NO MATCH
// --------------------------------------------------

} else if (data.status === "NO_MATCH") {

  message += `

원하시면 조건을 조정해서 다시 확인해드릴 수 있습니다.

예를 들어,
• 도착 가능 날짜를 조금 늦춰서 검색
• 현재 일정 중 가장 빠른 도착편 확인
• 특정 선사를 지정하여 재검색`;

// --------------------------------------------------
// 6. NEEDS CLARIFICATION
// --------------------------------------------------

} else if (data.status === "NEEDS_CLARIFICATION") {

  message += `

💬 일정 재검색을 위해 한 가지 확인이 필요합니다.

${value(
  data.clarification_question ??
  "검색 조건을 조금 더 구체적으로 알려주세요."
)}

조건을 알려주시면 해당 내용을 반영해서 다시 검색하겠습니다.`;


// --------------------------------------------------
// 7. 예상하지 못한 status
// --------------------------------------------------

} else {

  message += `

⚠️ 검색 결과를 정상적으로 분류하지 못했습니다.

잠시 후 다시 시도해 주세요.`;
}


// --------------------------------------------------
// 8. Return
// --------------------------------------------------

return [
  {
    json: {
      ...input,
      telegram_message: message.trim()
    }
  }
];
